package com.example.orders.messaging;

import com.example.orders.config.KafkaTopics;
import com.example.orders.events.OrderCreated;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.SendResult;
import org.springframework.stereotype.Component;

import java.util.concurrent.CompletableFuture;

@Component
public class OrderEventPublisher {

    private static final Logger log = LoggerFactory.getLogger(OrderEventPublisher.class);

    private final KafkaTemplate<String, OrderCreated> template;

    public OrderEventPublisher(KafkaTemplate<String, OrderCreated> template) {
        this.template = template;
    }

    public CompletableFuture<SendResult<String, OrderCreated>> publish(OrderCreated event) {
        String key = event.orderId().toString();       // same order, same partition
        return template.send(KafkaTopics.ORDER_EVENTS, key, event)
                .whenComplete((result, ex) -> {
                    if (ex != null) {
                        log.error("publish failed orderId={}", key, ex);
                    } else {
                        var md = result.getRecordMetadata();
                        log.info("published orderId={} partition={} offset={}",
                                key, md.partition(), md.offset());
                    }
                });
    }
}

