import java.util.*;
import java.util.stream.*;

public class MiniLog {

    record Rec(String key, String value, int partition, long offset) { }

    static class Topic {
        final List<List<Rec>> partitions = new ArrayList<>();
        Topic(int n) { for (int i = 0; i < n; i++) partitions.add(new ArrayList<>()); }
        Rec append(String key, String value) {
            int p = Math.floorMod(key.hashCode(), partitions.size());
            List<Rec> log = partitions.get(p);
            Rec r = new Rec(key, value, p, log.size());
            log.add(r);
            return r;
        }
    }

    static class Group {
        final Topic topic;
        final Map<Integer, Long> committed = new HashMap<>();
        final Map<String, List<Integer>> assignment = new TreeMap<>();
        Group(Topic t) {
            topic = t;
            for (int p = 0; p < t.partitions.size(); p++) committed.put(p, 0L);
        }

        void rebalance(Collection<String> members) {
            assignment.clear();
            List<String> ms = new ArrayList<>(members); Collections.sort(ms);
            for (String m : ms) assignment.put(m, new ArrayList<>());
            for (int p = 0; p < topic.partitions.size(); p++)
                assignment.get(ms.get(p % ms.size())).add(p);
            System.out.println("rebalance -> " + assignment);
        }

        // Poll up to max records; process; commit only every commitEvery records.
        List<Rec> poll(String member, int max) {
            List<Rec> out = new ArrayList<>();
            for (int p : assignment.getOrDefault(member, List.of())) {
                long off = pos.getOrDefault(member + p, committed.get(p));
                List<Rec> log = topic.partitions.get(p);
                while (off < log.size() && out.size() < max) out.add(log.get((int) off++));
                pos.put(member + p, off);
            }
            return out;
        }
        final Map<String, Long> pos = new HashMap<>();
        void commit(String member) {
            for (int p : assignment.getOrDefault(member, List.of()))
                if (pos.containsKey(member + p)) committed.put(p, pos.get(member + p));
        }
        void forgetPositions() { pos.clear(); }
    }

    public static void main(String[] args) {
        Topic orders = new Topic(3);
        for (int i = 1; i <= 9; i++) {
            Rec r = orders.append("order-" + (i % 4), "event-" + i);
            System.out.printf("produced %-8s -> partition %d offset %d%n",
                r.key(), r.partition(), r.offset());
        }
        System.out.println("-- per-key ordering check");
        for (int p = 0; p < 3; p++)
            System.out.println("partition " + p + ": " + orders.partitions.get(p).stream()
                .map(r -> r.key() + "/" + r.value())
                .collect(Collectors.joining(", ")));

        Group g = new Group(orders);
        g.rebalance(List.of("A"));
        List<Rec> batch = g.poll("A", 4);
        System.out.println("A polled " + batch.stream().map(Rec::value).toList());
        g.commit("A");
        System.out.println("A committed " + g.committed);

        g.rebalance(List.of("A", "B"));
        g.forgetPositions();
        System.out.println("-- A polls 3 more, processes them, crashes BEFORE commit");
        List<Rec> more = g.poll("A", 3);
        System.out.println("A processed " + more.stream().map(Rec::value).toList()
            + " (not committed)");

        g.rebalance(List.of("B"));
        g.forgetPositions();
        List<Rec> redo = g.poll("B", 100);
        System.out.println("B polled " + redo.stream().map(Rec::value).toList());
        Set<String> seen = new HashSet<>();
        Stream.concat(batch.stream(), Stream.concat(more.stream(), redo.stream()))
            .forEach(r -> {
                if (!seen.add(r.value()))
                    System.out.println("DUPLICATE delivery: " + r.value());
            });
        System.out.println("distinct events delivered: " + seen.size() + " of 9");
    }
}

package com.example.payments.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaOperations;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.util.backoff.ExponentialBackOff;

@Configuration
public class KafkaConsumerConfig {

    @Bean
    DefaultErrorHandler errorHandler(KafkaOperations<Object, Object> template) {
        var recoverer = new DeadLetterPublishingRecoverer(template);
        var backOff = new ExponentialBackOff(500L, 2.0);   // 0.5 s, 1 s, 2 s, ...
        backOff.setMaxAttempts(4);                         // 4 retries, 5 deliveries
        backOff.setMaxInterval(5_000L);
        var handler = new DefaultErrorHandler(recoverer, backOff);
        handler.addNotRetryableExceptions(IllegalArgumentException.class);
        return handler;
    }
}

