import java.util.*;

public class Outbox {
    /** Tiny atomic store: tx() rolls back every table if the body throws. */
    static class Db {
        List<String> orders = new ArrayList<>();
        List<String[]> outbox = new ArrayList<>();      // {id, payload, sent}

        void tx(Runnable body) {
            List<String> o = new ArrayList<>(orders);
            List<String[]> ob = new ArrayList<>();
            for (String[] r : outbox) ob.add(r.clone());
            try {
                body.run();
            } catch (RuntimeException e) {
                orders = o;
                outbox = ob;
                throw e;
            }
        }
    }

    static final List<String> broker = new ArrayList<>();

    static void dualWrite(Db db, String id, boolean crashAfterCommit) {
        db.tx(() -> db.orders.add(id));                 // 1. commit to the database
        if (crashAfterCommit) throw new IllegalStateException("process killed");
        broker.add("OrderCreated:" + id);               // 2. publish (skipped on crash)
    }

    static void outboxWrite(Db db, String id, boolean crashAfterCommit) {
        db.tx(() -> {                                   // one atomic transaction
            db.orders.add(id);
            db.outbox.add(new String[] {id, "OrderCreated:" + id, "false"});
        });
        if (crashAfterCommit) throw new IllegalStateException("process killed");
    }
    static void relay(Db db, boolean crashBeforeMarkSent) {
        for (String[] row : db.outbox) {
            if (row[2].equals("true")) continue;
            broker.add(row[1]);
            if (crashBeforeMarkSent) throw new IllegalStateException("relay died");
            row[2] = "true";
        }
    }

    static void attempt(Runnable r) {
        try {
            r.run();
        } catch (IllegalStateException e) {
            System.out.println("  !! " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        Db a = new Db();
        attempt(() -> dualWrite(a, "o-1", true));
        System.out.println("dual write   -> orders=" + a.orders + " broker=" + broker);

        broker.clear();
        Db b = new Db();
        attempt(() -> outboxWrite(b, "o-1", true));
        System.out.println("outbox write -> orders=" + b.orders + " outbox rows="
            + b.outbox.size() + " broker=" + broker);
        attempt(() -> relay(b, true));
        relay(b, false);
        System.out.println("relay restarted -> broker=" + broker);
    }
}

package com.example.orders.outbox;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "outbox_event")
public class OutboxEvent {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String aggregateId;          // used as the Kafka key

    @Column(nullable = false)
    private String topic;
    @Column(nullable = false, columnDefinition = "text")
    private String payload;              // JSON

    @Column(nullable = false)
    private Instant createdAt;

    private Instant sentAt;

    protected OutboxEvent() { }

    public OutboxEvent(UUID id, String aggregateId, String topic, String payload) {
        this.id = id;
        this.aggregateId = aggregateId;
        this.topic = topic;
        this.payload = payload;
        this.createdAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getAggregateId() { return aggregateId; }
    public String getTopic() { return topic; }
    public String getPayload() { return payload; }
    public void markSent() { this.sentAt = Instant.now(); }
}

package com.example.orders.outbox;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

import java.util.List;
import java.util.UUID;

public interface OutboxRepository extends JpaRepository<OutboxEvent, UUID> {

    @Query(value = """
            SELECT * FROM outbox_event
            WHERE sent_at IS NULL
            ORDER BY created_at
            LIMIT :batch
            FOR UPDATE SKIP LOCKED
            """, nativeQuery = true)
    List<OutboxEvent> lockNextBatch(int batch);
}

package com.example.orders.outbox;

import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.concurrent.TimeUnit;

@Component
public class OutboxRelay {

    private final OutboxRepository repository;
    private final KafkaTemplate<String, String> template;

    public OutboxRelay(OutboxRepository repository, KafkaTemplate<String, String> template) {
        this.repository = repository;
        this.template = template;
    }
    @Scheduled(fixedDelay = 500)
    @Transactional
    public void publishPending() throws Exception {
        for (OutboxEvent e : repository.lockNextBatch(100)) {
            template.send(e.getTopic(), e.getAggregateId(), e.getPayload())
                    .get(10, TimeUnit.SECONDS);      // wait for the broker ack
            e.markSent();                            // flushed at commit
        }
    }
}

