import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentService {

    private final PaymentRepository payments;
    private final ProcessedEventRepository processed;

    public PaymentService(PaymentRepository payments, ProcessedEventRepository processed) {
        this.payments = payments;
        this.processed = processed;
    }

    @Transactional
    public void authorise(OrderCreated event) {
        try {
            processed.saveAndFlush(new ProcessedEvent(event.eventId()));   // unique id
        } catch (DataIntegrityViolationException duplicate) {
            return;                                                         // already handled
        }
        payments.save(Payment.authorised(event.orderId(), event.total()));
    }
}

package com.example.orders.amqp;

import org.springframework.amqp.core.Binding;
import org.springframework.amqp.core.BindingBuilder;
import org.springframework.amqp.core.DirectExchange;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.core.QueueBuilder;
