import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
import org.springframework.amqp.support.converter.MessageConverter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class RabbitConfig {

    public static final String EXCHANGE = "orders.x";
    public static final String DLX = "orders.dlx";

    @Bean
    TopicExchange ordersExchange() {
        return new TopicExchange(EXCHANGE);
    }

    @Bean
    DirectExchange deadLetterExchange() {
        return new DirectExchange(DLX);
    }

    @Bean
    Queue billingQueue() {
        return QueueBuilder.durable("billing.q")
                .deadLetterExchange(DLX)
                .deadLetterRoutingKey("billing.dead")
                .build();
    }

    @Bean
    Queue billingDeadLetterQueue() {
        return QueueBuilder.durable("billing.dlq").build();
    }

    @Bean
    Binding billingBinding(Queue billingQueue, TopicExchange ordersExchange) {
        return BindingBuilder.bind(billingQueue).to(ordersExchange).with("order.*");
    }

    @Bean
    Binding billingDeadBinding(Queue billingDeadLetterQueue, DirectExchange deadLetterExchange) {
        return BindingBuilder.bind(billingDeadLetterQueue).to(deadLetterExchange)
                .with("billing.dead");
    }

    @Bean
    MessageConverter jsonMessageConverter() {
        return new Jackson2JsonMessageConverter();
    }
}

