import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Stampede {
    static final AtomicInteger dbCalls = new AtomicInteger();

    static String loadFromDb(String key) {
        dbCalls.incrementAndGet();
        try { Thread.sleep(200); }
        catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return "value-of-" + key;
    }

    static long run(String title, boolean singleFlight) throws Exception {
        dbCalls.set(0);
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        ConcurrentHashMap<String, Object> locks = new ConcurrentHashMap<>();
        int clients = 200;
        CountDownLatch go = new CountDownLatch(1);
        long t0 = System.nanoTime();
        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < clients; i++) {
                pool.submit(() -> {
                    go.await();
                    String v = cache.get("product:42");
                    if (v == null) {
                        if (singleFlight) {
                            Object lock = locks.computeIfAbsent("product:42", k -> new Object());
                            synchronized (lock) {
                                v = cache.get("product:42");
                                if (v == null) {
                                    v = loadFromDb("product:42");
                                    cache.put("product:42", v);
                                }
                            }
                        } else {
                            v = loadFromDb("product:42");
                            cache.put("product:42", v);
                        }
                    }
                    return v;
                });
            }
            go.countDown();
        }
        long ms = (System.nanoTime() - t0) / 1_000_000;
        System.out.printf("%-34s clients=%d  db calls=%d%n",
            title, clients, dbCalls.get());
        return ms;
    }

    public static void main(String[] a) throws Exception {
        run("no protection (cold key)", false);
        run("single flight (lock + re-check)", true);
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

public class Graceful {
    static String attempt(int stopDelaySeconds, int port) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", port), 0);
        server.createContext("/slow", ex -> {
            try { Thread.sleep(1000); } catch (InterruptedException e) { }
            byte[] body = "done".getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, body.length);
            ex.getResponseBody().write(body);
            ex.close();
        });
        server.start();
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
        var req = HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + port + "/slow")).build();
        var future = client.sendAsync(req, HttpResponse.BodyHandlers.ofString());
        Thread.sleep(300);                       // request is now in flight
        server.stop(stopDelaySeconds);           // SIGTERM equivalent
        String result;
        try { result = "HTTP " + future.get().statusCode() + " " + future.get().body(); }
        catch (Exception e) { result = "client error: " + e.getCause().getClass().getSimpleName(); }
        return String.format("stop(%d): in-flight request -> %s", stopDelaySeconds, result);
    }
    public static void main(String[] a) throws Exception {
        System.out.println(attempt(0, 21699));
        System.out.println(attempt(5, 21698));
    }
}

