public class Base62 {
    private static final String ALPHABET =
        "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    static String encode(long id) {
        if (id == 0) return "0";
        StringBuilder sb = new StringBuilder();
        while (id > 0) {
            sb.append(ALPHABET.charAt((int) (id % 62)));
            id /= 62;
        }
        return sb.reverse().toString();
    }

    static long decode(String code) {
        long id = 0;
        for (char c : code.toCharArray()) id = id * 62 + ALPHABET.indexOf(c);
        return id;
    }

    public static void main(String[] args) {
        long[] ids = {1, 61, 62, 125, 1_000_000L, 3_521_614_606_207L};
        for (long id : ids) {
            String code = encode(id);
            System.out.printf("id=%-16d code=%-8s decoded=%d%n", id, code, decode(code));
        }
        System.out.println("62^7 = " + (long) Math.pow(62, 7) + " codes of length 7");
    }
}

