package com.example.orders.service;

import com.example.orders.api.CreateOrderRequest;
import com.example.orders.api.OrderView;
import com.example.orders.domain.Order;
import com.example.orders.domain.OrderRepository;
import com.example.orders.outbox.OutboxEvent;
import com.example.orders.outbox.OutboxRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
public class OrderService {

    private final OrderRepository orders;
    private final OutboxRepository outbox;
    private final ObjectMapper mapper;
    private final Counter placed;

    public OrderService(OrderRepository orders, OutboxRepository outbox,
                        ObjectMapper mapper, MeterRegistry registry) {
        this.orders = orders;
        this.outbox = outbox;
        this.mapper = mapper;
        this.placed = Counter.builder("orders.placed").register(registry);
    }

    @Transactional
    public OrderView place(UUID idempotencyKey, CreateOrderRequest request) {
        return orders.findByCustomerIdAndIdempotencyKey(request.customerId(), idempotencyKey)
                .map(OrderView::from)                                // retry: same answer
                .orElseGet(() -> create(idempotencyKey, request));
    }

    private OrderView create(UUID idempotencyKey, CreateOrderRequest request) {
        Order order = orders.save(Order.pending(idempotencyKey, request));
        try {
            outbox.save(new OutboxEvent(UUID.randomUUID(), order.getId().toString(),
                    "orders.events", mapper.writeValueAsString(OrderView.from(order))));
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("cannot serialise event", e);   // rolls back
        }
        placed.increment();
        return OrderView.from(order);
    }
}
